import { describe, expect, it, vi } from 'vitest';
import { siteSections } from '../src/lib/site-sections.ts';

// The citations module is generated by vite.config.ts when the site is built.
vi.mock('virtual:source-citations', () => ({ sourceCitations: {} }));
// The nations' list is built by vite.config.ts the same way.
vi.mock('virtual:section-lists', async () => {
	const { nationIndexRows } = await import('../src/lib/server/nation-index.ts');
	const rows = nationIndexRows();
	return { nationNames: rows.map((row) => [row.name, row.id]), nationCount: rows.filter((row) => row.entityType === 'native-nation').length };
});

const { builtSections, sectionContents } = await import('#lib/server/section-contents.ts');

describe('the pages of each section, for the sidebar’s second column', () => {
	it('has contents for every section with pages, the essays from the database', () => {
		const opening = siteSections.filter((section) => section.opens).map((section) => section.link.slice(1));
		expect(opening.filter((name) => !['foundations', 'essays'].includes(name)).sort()).toEqual([...builtSections].sort());
		expect(siteSections.filter((section) => section.opens && !section.built)).toEqual([]);
	});

	it('lists each section’s own pages and its long list with working addresses', async () => {
		const nations = await sectionContents('nations');
		expect(nations?.pages.map((item) => item.link)).toEqual(['/nations/law', '/nations/map', '/nations/timeline', '/nations/recourse', '/nations/data', '/nations/federal-offices', '/nations/coverage']);
		// "View all" beside the list opens the table of every nation.
		expect(nations?.entries).toEqual({ noun: 'nations', items: [], list: 'nations', title: 'Native nations', viewAll: '/nations' });
		const { withSharedLists } = await import('#lib/section-lists.ts');
		const shared = withSharedLists(nations)?.entries;
		const filled = shared?.items ?? [];
		expect(shared?.count).toBeGreaterThan(500);
		expect(shared?.count).toBeLessThan(filled.length);
		expect(filled.length).toBeGreaterThan(500);
		expect(filled.some((item) => item.link === '/nations/navajo-nation')).toBe(true);
		expect((await sectionContents('library'))?.pages[0]?.link).toBe('/copies');
		const glossary = await sectionContents('glossary');
		expect(glossary?.pages).toEqual([]);
		expect(glossary?.entries?.items.every((item) => item.link.startsWith('/glossary/'))).toBe(true);
		const stories = await sectionContents('stories');
		expect(stories?.pages).toEqual([{ label: 'All stories', link: '/stories' }]);
		expect(stories?.entries?.items.every((item) => item.link.startsWith('/stories/'))).toBe(true);
		// The first call reads every record (about 27,000), which takes 15 to 30 seconds on a CI runner.
	}, 60_000);

	it('lists the Sponsorship levels page under Sponsorship', async () => {
		expect((await sectionContents('sponsor'))?.pages).toEqual([
			{ label: 'Sponsorship', link: '/sponsor' },
			{ label: 'Sponsorship levels', link: '/sponsor/levels' }
		]);
	});

	it('has nothing for a section it does not know', async () => {
		expect(await sectionContents('charter')).toBeUndefined();
		expect(await sectionContents('constructor')).toBeUndefined();
	});
});
